const QT_DRUGS_V35=['Amiodaron','Sotalol','Prokainamid','Haloperidol','Droperidol','Ondansetron','Azitromisin','Klaritromisin','Eritromisin','Moksifloksasin','Levofloksasin','Flukonazol','Vorikonazol','Citalopram','Escitalopram','Metadon'];
const K_RISK_V35=['Spironolakton','Eplerenon','Lisinopril','Enalaprilat','Losartan','Valsartan','Sakubitril/valsartan','TMP-SMX','Potasyum klorür IV','Potasyum fosfat IV'];
const NEPHRO_V35=['Vancomycin','Gentamisin','Amikasin','Tobramisin','Lipozomal amfoterisin B','Foskarnet','Cidofovir','Polimiksin B','Ketorolak','İbuprofen IV/PO','Asiklovir IV'];
