function drugFromListV35(name,list){return drugMatches(name,list)}
function listHitsV35(names,list){return names.filter(n=>drugFromListV35(n,list))}
function detectSafetyV35(names,patient={}){
  const out=[],crcl=patient.crcl??null,cp=patient.cp??null;
  const qt=listHitsV35(names,QT_DRUGS_V35); if(qt.length>=2) out.push({id:'qt',sev:'critical',title:'QT uzaması / torsades risk kümesi',text:`Birden fazla QT riski taşıyan ilaç seçildi: ${qt.map(displayName).join(', ')}. EKG/QTc ve K/Mg değerlendirilmelidir; ilaç-özel ürün bilgileri kontrol edilmelidir.`,source:V35_SOURCES.ondansetron,tags:['QT','EKG','K/Mg']});
  const kr=listHitsV35(names,K_RISK_V35); if(kr.length>=2 && (crcl==null||crcl<60)) out.push({id:'hyperk',sev:'high',title:'Hiperkalemi risk kümesi',text:`${kr.map(displayName).join(', ')} birlikte ve/veya renal fonksiyon bozukluğu bağlamında serum K ve kreatinin için yakın izlem gerektirir. TMP-SMX ürün bilgisi renal yetmezlik veya potasyum yükselten ilaçlarla kullanımda yakın K izlemi önerir.`,source:V35_SOURCES.tmp,tags:['K+','KREATİNİN']});
  const neph=listHitsV35(names,NEPHRO_V35); if(neph.length>=2) out.push({id:'nephro',sev:'high',title:'Birden fazla nefrotoksik ilaç',text:`${neph.map(displayName).join(', ')}. Toplam nefrotoksik yük nedeniyle kreatinin/CrCl trendi, sıvı durumu ve gereksiz eşzamanlılık gözden geçirilmelidir. Aminoglikozid ürün bilgileri diğer nefrotoksik ajanlarla eşzamanlı kullanım konusunda uyarır.`,source:V35_SOURCES.amikacin,tags:['NEFROTOKSİSİTE','RENAL']});
  const linez=names.find(n=>drugFromListV35(n,['Linezolid'])); const serotonergic=names.filter(n=>{const d=getDrug(n);return /SSRI|SNRI|TCA|NaSSA|seroton|tramadol|fentanil|lityum|lithium/i.test((d?.class||'')+' '+(d?.name||'')+' '+(d?.displayName||'')+' '+(d?.tags||[]).join(' '));}); if(linez&&serotonergic.filter(n=>n!==linez).length) out.push({id:'serotonin',sev:'critical',title:'Serotonin sendromu riski',text:`Linezolid ile serotonerjik ilaç(lar): ${serotonergic.filter(n=>n!==linez).map(displayName).join(', ')}. Ürün bilgisine göre serotonin sendromu açısından izlem ve tedavi alternatiflerinin değerlendirilmesi gerekir.`,source:V35_SOURCES.linezolid,tags:['SEROTONİN','LINEZOLİD']});
  const ac=listHitsV35(names,ANTICOAG_V35),ap=listHitsV35(names,ANTIPLATELET_V35),ns=listHitsV35(names,NSAID_V35); if(ac.length&&(ap.length||ns.length)) out.push({id:'bleeding',sev:'critical',title:'Kanama riski — antitrombotik kombinasyon',text:`${[...ac,...ap,...ns].map(displayName).join(', ')}. Eşzamanlı antikoagülan/antiplatelet/NSAİİ kullanımı için endikasyon, süre, hemoglobin/CBC ve kanama bulguları yeniden değerlendirilmelidir.`,source:{name:'İlaç-özel ürün bilgileri / mevcut etkileşim kural seti',url:'https://dailymed.nlm.nih.gov/dailymed/',date:'Doğrulama '+V35_REVIEW_DATE},tags:['KANAMA','CBC']});
  if(ac.length>=2) out.push({id:'dup-anticoag',sev:'critical',title:'Duplicate antikoagülasyon',text:`Birden fazla antikoagülan seçildi: ${ac.map(displayName).join(', ')}. Geçiş/prosedür amacı yoksa eşzamanlılık doğrulanmalıdır.`,source:{name:'DrugSafe duplicate-class kuralı',url:'',date:'v3.5'},tags:['DUPLICATE','KANAMA']});
  if(crcl!=null && crcl<30){const li=names.filter(n=>drugFromListV35(n,['Lithium carbonate','Lithium citrate']));if(li.length)out.push({id:'lithium-renal',sev:'critical',title:'Lityum + ağır renal bozukluk',text:`CrCl ${crcl.toFixed(1)} mL/dk. Lityum ürün bilgisi CrCl <30 mL/dk için kullanımdan kaçınmayı belirtir; serum lityum ve renal durum ayrıca değerlendirilmelidir.`,source:V35_SOURCES.lithium,tags:['KONTRENDİKASYON','TDM','RENAL']});}
  if(cp!=null && cp>=7){const va=names.filter(n=>drugFromListV35(n,['Valproat','Valproic acid']));if(va.length)out.push({id:'valproate-hepatic',sev:'critical',title:'Valproat + belirgin hepatik hastalık sinyali',text:`Child–Pugh ${cpClass(cp)} bağlamında ${va.map(displayName).join(', ')} seçildi. Valproat ürün bilgisi hepatik hastalık veya belirgin hepatik disfonksiyonda kontrendikasyon bildirir; Child-Pugh tek başına bu tanıyı koymaz, klinik hepatik hastalık varlığı ayrıca doğrulanmalıdır.`,source:V35_SOURCES.valproate,tags:['HEPATİK','KONTRENDİKASYON']}); const du=names.filter(n=>drugFromListV35(n,['Duloxetine','Duloksetin']));if(du.length)out.push({id:'duloxetine-hepatic',sev:'high',title:'Duloksetin + kronik karaciğer hastalığı riski',text:'Duloksetin ürün bilgisi kronik karaciğer hastalığı kanıtı olan hastalarda kullanımdan kaçınmayı belirtir. Child-Pugh sonucu klinik kronik karaciğer hastalığıyla birlikte yorumlanmalıdır.',source:V35_SOURCES.duloxetine,tags:['HEPATİK','KAÇIN']});}
  return out;
}
