 const tdmTests=[['Vancomycin','AUC24/MIC'],['Gentamisin','TDM'],['Amikasin','TDM'],['Tobramisin','TDM'],['Digoksin','TDM'],['Lithium carbonate','TDM'],['Valproat','TDM'],['Linezolid','Rutin TDM değil'],['TMP-SMX','Rutin TDM değil']];for(const [drug,token] of tdmTests){const d=DB.drugs.find(x=>drugMatches(x.name,[drug])),r=d&&tdmRuleForV35(d.name),blob=(r?.mode||'')+' '+(r?.target||'');tests.push({id:++id,cat:'TDM / izlem',ok:!!r&&(token==='TDM'||norm(blob).includes(norm(token))||norm(r.mode).includes(norm(token))),title:drug,detail:r?`${r.mode} • ${r.target}`:'Kural bulunamadı'})}
