function renderValidationV35(){const lv=validateLiveV20(),tests=runReferenceValidationV35(),pass=tests.filter(x=>x.ok).length,total=tests.length,pct=total?Math.round(pass/total*1000)/10:0;const render=arr=>arr.map(x=>`<div class="validation-item"><div><div class="validation-title">${esc35(x.title)}</div><div class="validation-desc">${esc35(x.desc)}</div></div><div class="${x.ok?'okmark':'warnmark'}">${x.ok?'✓':'⚠'}</div></div>`).join('');$('liveValidation').innerHTML=render(lv);const quick=[{ok:pass===total,title:'Referans uyum/regresyon',desc:`${pass}/${total} test geçti.`},{ok:DB.drugs.length>=393,title:'Veritabanı bütünlüğü',desc:`${DB.drugs.length} benzersiz erişkin ilaç.`},{ok:TDM_RULES_V35.length>=9,title:'TDM/izlem kural seti',desc:`${TDM_RULES_V35.length} ilaç/ilaç grubu için yapılandırılmış kural.`},{ok:true,title:'Klinik validasyon etiketi',desc:'Skor klinik performans yüzdesi olarak sunulmaz.'}];$('regressionValidation').innerHTML=render(quick);const ring=$('validationScoreRing');if(ring)ring.style.setProperty('--score',pct+'%');if($('validationScoreText'))$('validationScoreText').textContent=`${pass}/${total}`;if($('validationCaseCount'))$('validationCaseCount').textContent=`${total} TEST`;if($('validationKpis'))$('validationKpis').innerHTML=[[pct+'%','Referans uyum'],[pass,'Geçen'],[total-pass,'Başarısız'],[total,'Toplam senaryo']].map(x=>`<div class="validation-kpi"><div class="n">${x[0]}</div><div class="t">${x[1]}</div></div>`).join('');const groups={};for(const t of tests)(groups[t.cat]??=[]).push(t);$('validationDetailsV35').innerHTML=Object.entries(groups).map(([cat,arr])=>`<div class="test-group"><div class="test-group-head"><span>${esc35(cat)}</span><span>${arr.filter(x=>x.ok).length}/${arr.length}</span></div>${arr.map(t=>`<div class="test-row"><div class="${t.ok?'ok':'fail'}">${t.ok?'✓':'✕'}</div><div><strong>${esc35(t.title)}</strong><div class="detail">${esc35(t.detail)}</div></div><div>${t.ok?'PASS':'REVIEW'}</div></div>`).join('')}</div>`).join('')}
