 if(r.status==='none')return {status:'none',sourceType:'Diyalize bağlı doz değişikliği yok',dose:dose||'Diyalize bağlı doz değişikliği yok',note,source:d.renalModel.sourceUrl,high:d.nephrotoxicity==='high'};
 if(r.status==='dose'||r.status==='timing')return {status:'dose',sourceType:`${mod.toUpperCase()} • ilaç-özel Stanford kuralı`,dose,note,source:d.renalModel.sourceUrl,high:d.nephrotoxicity==='high',band:{condition:mod.toUpperCase()+' • '+ctx}};
